head.script:
scwin.onpageload = function() {
	scwin.test = 0;
    var jsonData = [{
        "col1": "a1"
    }, {
        "col1": "a2"
    }, {
        "col1": "a3"
    }, {
        "col1": "a4"
    }, {
        "col1": "a5"
    }];
    main_dataList1.setJSON(jsonData);
};
scwin.onpageunload = function() {};
scwin.trigger1_onclick = function(e) {
    scwin.test += 1;
    var tabObj = {
        label: "임시화면",
        closable: true,
        openAction: "exist"
    };
    var contObj = {
        frameMode: "wframe",
        scope: true,
        src: "tabControl_openAction_exist_wframe_WPFF-398_(WSQ-4070)_sub.xml",
        alwaysDraw: false,
        title: "test",
        dataObject: {
            type: "json",
            name: "param1",
            data: {
                "test1": "d_test11_" + scwin.test,
                "test2": "d_test22"
            }
        }
    };
    tabControl1.addTab("test111", tabObj, contObj);
};
scwin.checkVal = function() {
    return WebSquare.wUnit.getJq('#tabControl1_contents_test111_body_input1').val() == 'd_test11_2';
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
